// Room helpers for Grid(5,base10,rgby). Generated; do not edit.

type Colour = string;
type Suit = "spades" | "hearts" | "diamonds" | "clubs";
/** Bigger is better; arrays compare like a league table (first number first). */
type Score = number | number[];

declare class Cell {
  private constructor();
  /** 0 = top row / left column. */
  readonly row: number;
  readonly col: number;
  /** What's printed on it: "7", "B", "K♥". */
  readonly symbol: string;
  /** Points: digits as they are, cards A=1 .. K=13. */
  readonly value: number;
  readonly colour: Colour;
  readonly left: Cell | null;
  readonly right: Cell | null;
  readonly up: Cell | null;
  readonly down: Cell | null;
  readonly upLeft: Cell | null;
  readonly upRight: Cell | null;
  readonly downLeft: Cell | null;
  readonly downRight: Cell | null;
  /** The 2 to 4 cells touching its sides. */
  readonly neighbours: Cell[];
  /** The 3 to 8 cells around it, corners included. */
  readonly surrounding: Cell[];
  readonly onEdge: boolean;
}

declare class Grid {
  private constructor();
  readonly size: 5;
  /** Row by row from the top-left. */
  readonly cells: Cell[];
  readonly rows: Cell[][];
  readonly columns: Cell[][];
  readonly diagonals: Cell[][];
  readonly edgeCells: Cell[];
  /** Every colour this kind of grid can use, in rainbow order. */
  readonly palette: Colour[];
  cell(row: number, col: number): Cell;
  quarterTurn(cell: Cell): Cell;
  reachable(start: Cell | readonly Cell[], through: (cell: Cell) => boolean): Cell[];
  regions(same: (a: Cell, b: Cell) => boolean): Cell[][];
}

declare function nextColour(colour: Colour): Colour;
declare function mix(a: Colour, b: Colour): Colour | null;
declare function __decode(wire: string): Grid;

/** What a move helper returns. Return a list of these from agent(...). */
interface MutatorCall { readonly __m: string }
/** Moves wrapped by the commit clause (only rooms with commitClause offer the wrapper). */
interface CommitClause { readonly __commit: "if-improves"; readonly calls: readonly MutatorCall[] }
declare function __encode_calls(calls: MutatorCall | readonly MutatorCall[] | CommitClause | null | undefined): string;

/** An area made by row(2), column(0), diagonal(), square(1, 1), ring(0), edge(), middle(), everything() or busiestLine(). */
interface AreaRef { readonly kind: string; readonly region?: unknown }
type CellRef = Cell | readonly [number, number];
/** Where a move acts: an area, a cell, or a list of cells such as grid.rows[2] or grid.diagonals[0]. */
type Area = AreaRef | CellRef | readonly CellRef[];
/** A whole row or column: row(2), column(1), grid.rows[2], grid.columns[1] (or busiestLine() for majority). */
type LineRef = AreaRef | readonly CellRef[];
type Layer = "both" | "colour" | "symbol";
type Turn = "anticlockwise" | "clockwise" | "half" | "flip_left_right" | "flip_up_down" | "transpose" | "antitranspose";
declare function row(i: number): AreaRef;
declare function column(i: number): AreaRef;
declare function diagonal(): AreaRef;
declare function otherDiagonal(): AreaRef;
declare function square(top: number, left: number, size?: 2 | 3): AreaRef;
declare function ring(depth?: number): AreaRef;
declare function edge(): AreaRef;
declare function middle(): AreaRef;
declare function everything(): AreaRef;
declare function busiestLine(): AreaRef;
declare function swapCells(a: CellRef, b: CellRef, what?: Layer): MutatorCall;

declare function slide(line: LineRef, steps?: number, what?: Layer): MutatorCall;

declare function reverse(line: LineRef, what?: Layer): MutatorCall;

declare function swapRows(a: number, b: number): MutatorCall;
declare function swapColumns(a: number, b: number): MutatorCall;

declare function turnSquare(where: Area, how: Turn): MutatorCall;

declare function turnGrid(how: Turn): MutatorCall;

declare function sortLine(line: LineRef, biggestFirst?: boolean): MutatorCall;

declare function mirrorLine(line: LineRef, keep?: "first" | "second", what?: Layer): MutatorCall;
declare function mirrorGrid(keep: string, what?: Layer): MutatorCall;

declare function paint(where: Area, colour: string): MutatorCall;

declare function recolour(where: Area, oldColour: string, newColour: string): MutatorCall;

declare function swapColours(where: Area, a: string, b: string): MutatorCall;

declare function rainbowStep(where: Area, steps?: number): MutatorCall;

declare function rainbowLine(line: LineRef, start: string, backwards?: boolean): MutatorCall;
declare function alternateLine(line: LineRef, a: string, b: string): MutatorCall;

declare function stripes(start: string, down?: boolean, backwards?: boolean): MutatorCall;
declare function diagonalRainbow(start: string, otherWay?: boolean, backwards?: boolean): MutatorCall;
declare function chessboard(a: string, b: string): MutatorCall;

declare function majority(line: LineRef): MutatorCall;

declare function write(where: Area, symbol: string | number): MutatorCall;

declare function countOn(where: Area, steps?: number): MutatorCall;

declare function countAlong(line: LineRef, start: string | number, down?: boolean): MutatorCall;

declare function swapNumbers(where: Area, a: string | number, b: string | number): MutatorCall;

declare function paintEvenOdd(where: Area, even: string, odd: string): MutatorCall;
declare function paintByNumber(where: Area, shift?: number): MutatorCall;
declare function paintRedBlack(where: Area, red: string, black: string): MutatorCall;

declare function stamp(where: Area, colour: string, symbol: string | number): MutatorCall;

declare function countMines(where: Area, mineColour: string): MutatorCall;

declare function mixPaint(where: Area, a: string, b: string): MutatorCall;

